     1	package hotel.documents;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.rooms.Room;
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.util.Locale;
     8	
     9	/** The texts of the three documents. */
    10	public final class DocumentTexts {
    11	
    12	    private DocumentTexts() {
    13	    }
    14	
    15	    public static String personReceipt(Reservation reservation, Room room) {
    16	        StringBuilder text = new StringBuilder();
    17	        text.append("Comprovante de reserva nº ").append(reservation.id()).append('\n');
    18	        text.append("Hóspede: ").append(reservation.guest().name())
    19	                .append(" (CPF ").append(reservation.guest().cpf()).append(")\n");
    20	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    21	        int nights = reservation.price().nights();
    22	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
    23	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
    24	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    25	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
    26	        if (reservation.price().discount().signum() > 0) {
    27	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
    28	        }
    29	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
    30	        return text.toString();
    31	    }
    32	
    33	    public static String companyInvoice(Reservation reservation, Room room) {
    34	        StringBuilder text = new StringBuilder();
    35	        text.append("Fatura de hospedagem nº ").append(reservation.id()).append('\n');
    36	        text.append("Empresa: ").append(reservation.guest().companyName())
    37	                .append(" (CNPJ ").append(reservation.guest().companyCnpj()).append(")\n");
    38	        text.append("Hóspede: ").append(reservation.guest().name()).append('\n');
    39	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    40	        int nights = reservation.price().nights();
    41	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
    42	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
    43	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    44	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
    45	        if (reservation.price().discount().signum() > 0) {
    46	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
    47	        }
    48	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
    49	        BigDecimal withheldTax = reservation.price().total().multiply(new BigDecimal("0.05"))
    50	                .setScale(2, RoundingMode.HALF_EVEN);
    51	        text.append("ISS retido (5%): ").append(TextFormat.money(withheldTax)).append('\n');
    52	        return text.toString();
    53	    }
    54	
    55	    public static String foreignReceipt(Reservation reservation, Room room) {
    56	        StringBuilder text = new StringBuilder();
    57	        text.append("Booking receipt no. ").append(reservation.id()).append('\n');
    58	        text.append("Guest: ").append(reservation.guest().name()).append(" (passport ")
    59	                .append(reservation.guest().passport()).append(", ").append(reservation.guest().country())
    60	                .append(")\n");
    61	        text.append("Room: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    62	        int nights = reservation.price().nights();
    63	        text.append("Check-in: ").append(reservation.checkIn()).append(" | Check-out: ")
    64	                .append(reservation.checkOut()).append(" | ").append(nights)
    65	                .append(nights == 1 ? " night" : " nights").append('\n');
    66	        text.append("Nights: ").append(brl(reservation.price().subtotal())).append('\n');
    67	        if (reservation.price().discount().signum() > 0) {
    68	            text.append("Discount: ").append(brl(reservation.price().discount())).append('\n');
    69	        }
    70	        text.append("Total: ").append(brl(reservation.price().total())).append('\n');
    71	        return text.toString();
    72	    }
    73	
    74	    private static String brl(BigDecimal amount) {
    75	        return "BRL " + String.format(Locale.US, "%,.2f", amount);
    76	    }
    77	}
