    30	        this.amountPaid = PriceCalculator.cents(BigDecimal.ZERO);
    31	    }
    32	
    33	    public long id() {
    34	        return id;
    35	    }
    36	
    37	    public int roomNumber() {
    38	        return roomNumber;
    39	    }
    40	
    41	    public Guest guest() {
    42	        return guest;
    43	    }
    44	
    45	    public LocalDate checkIn() {
    46	        return checkIn;
    47	    }
    48	
    49	    public LocalDate checkOut() {
    50	        return checkOut;
    51	    }
    52	
    53	    public int guests() {
    54	        return guests;
    55	    }
    56	
    57	    public RatePlan ratePlan() {
    58	        return ratePlan;
    59	    }
    60	
    61	    public Price price() {
    62	        return price;
    63	    }
    64	
    65	    public ReservationStatus status() {
    66	        return status;
    67	    }
    68	
    69	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
    70	    public BigDecimal amountPaid() {
    71	        return amountPaid;
    72	    }
    73	
    74	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
    75	    public BigDecimal refund() {
    76	        return refund;
    77	    }
    78	
    79	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
    80	    public boolean isPaid() {
    81	        return status == ReservationStatus.CONFIRMED
    82	                || status == ReservationStatus.CHECKED_IN
    83	                || status == ReservationStatus.CHECKED_OUT;
    84	    }
    85	
    86	    /** The money the inn keeps from this reservation. */
    87	    public BigDecimal amountKept() {
    88	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    89	    }
    90	
    91	    void changeStatus(ReservationStatus newStatus) {
    92	        this.status = newStatus;
    93	    }
    94	
    95	    void confirmPayment() {
    96	        this.status = ReservationStatus.CONFIRMED;
    97	        this.amountPaid = price.total();
    98	    }
    99	
   100	    void cancel(BigDecimal refundAmount) {
   101	        this.status = ReservationStatus.CANCELLED;
   102	        this.refund = refundAmount;
   103	    }
   104	
   105	    boolean overlaps(int otherRoomNumber, LocalDate otherCheckIn, LocalDate otherCheckOut) {
   106	        return roomNumber == otherRoomNumber
   107	                && checkIn.isBefore(otherCheckOut)
   108	                && otherCheckIn.isBefore(checkOut);
   109	    }
